import assert from "node:assert/strict";
import { mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { spawnSync } from "node:child_process";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));

// This is deliberately an independent consumer of the module's exported type.
const consumerSource = `
import type { MetricDefinition } from "./schema/src/metric-registry.ts";

type IsAny<Value> = 0 extends (1 & Value) ? true : false;
type IsRequiredString<Value> =
  Value extends { observation_key: infer Key }
    ? IsAny<Key> extends true
      ? false
      : [Key] extends [never]
        ? false
        : Key extends string
          ? true
          : false
    : false;
type Assert<Condition extends true> = Condition;

type ObservationKeyIsPublicAndRequired = Assert<IsRequiredString<MetricDefinition>>;

declare const metric: MetricDefinition;
const observationKey: string = metric.observation_key;
void observationKey;
void (null as unknown as ObservationKeyIsPublicAndRequired);
`;

test("MetricDefinition exposes a required string observation_key to public typed consumers", () => {
  const temporaryRoot = mkdtempSync(join(tmpdir(), "metric-definition-public-contract-"));

  try {
    symlinkSync(resolve(here, ".."), join(temporaryRoot, "schema"), "dir");
    const probePath = join(temporaryRoot, "consumer.ts");
    writeFileSync(probePath, consumerSource, "utf8");

    const compilation = spawnSync(
      "tsc",
      [
        "--noEmit",
        "--strict",
        "--target", "ES2022",
        "--module", "NodeNext",
        "--moduleResolution", "NodeNext",
        "--allowImportingTsExtensions",
        "--pretty", "false",
        probePath
      ],
      { encoding: "utf8" }
    );

    assert.equal(
      compilation.error,
      undefined,
      `TypeScript compiler could not run: ${compilation.error?.message ?? "unknown error"}`
    );
    assert.equal(
      compilation.status,
      0,
      `${compilation.stdout}${compilation.stderr}`
    );
  } finally {
    rmSync(temporaryRoot, { recursive: true, force: true });
  }
});
